/**
 * Overgenomen uit mobielebandenspecialist (scripts/build-plaatsen.js daar) — niet met de hand bewerken.
 *
 * Bron: drie open datasets met Nederlandse plaatsen (GeoNames via all-the-cities
 * en cities.json, plus de countries-states-cities database). GeoNames is leidend,
 * omdat die per plaats aangeeft of het om een zelfstandige woonplaats gaat of om
 * een wijk binnen een grotere plaats (featureCode PPLX). Wijken zijn eruit
 * gefilterd; anders zou de site pagina's krijgen voor buurten als Matengaarde of
 * Vogelkwartier in plaats van voor echte plaatsen.
 *
 * Buurplaatsen en het ankerpunt (dichtstbijzijnde duidelijk grotere plaats, met
 * afstand en windrichting) zijn berekend uit de coordinaten en dus feitelijk
 * juist. Snelwegen, N-wegen, wateren en knelpunten komen uit OpenStreetMap en
 * staan alleen ingevuld waar ze geverifieerd zijn — een leeg veld is bewust leeg.

 */

export const PROVINCIES = [
  "Groningen",
  "Friesland",
  "Drenthe",
  "Overijssel",
  "Flevoland",
  "Gelderland",
  "Utrecht",
  "Noord-Holland",
  "Zuid-Holland",
  "Zeeland",
  "Noord-Brabant",
  "Limburg",
] as const;

export type Provincie = (typeof PROVINCIES)[number];

export type Knelpunt = { naam: string; type: "tunnel" | "brug" | "knooppunt" };

/** Dichtstbijzijnde duidelijk grotere plaats, met echte afstand en richting. */
export type Anker = { slug: string; naam: string; km: number; richting: string };

export type Plaats = {
  naam: string;
  slug: string;
  provincie: Provincie;
  /** Inwoneraantal volgens GeoNames; 0 = onbekend (niet: nul inwoners). */
  inw: number;
  /** Slugs van werkelijke buurplaatsen, oplopend op afstand (max 22 km). */
  buren: string[];
  anker: Anker | null;
  snelwegen: string[];
  nWegen: string[];
  wateren: string[];
  knelpunten: Knelpunt[];
  coropRegio?: string;
};

