const bySlug = new Map(plaatsen.map((p) => [p.slug, p]));

export function getPlaats(slug: string): Plaats | undefined {
  return bySlug.get(slug);
}

export function plaatsSlugs(): string[] {
  return plaatsen.map((p) => p.slug);
}

/** Plaatsen gesorteerd op grootte — voor "populaire plaatsen"-lijsten. */
export const plaatsenOpGrootte: Plaats[] = [...plaatsen].sort(
  (a, b) => b.inw - a.inw,
);

/**
 * De grootste plaatsen krijgen daarnaast een eigen spoedpagina voor lekke banden
 * (/lekke-band/[stad]) en een pagina voor de seizoenswissel
 * (/winterbanden-wisselen/[stad]). Dat zijn andere zoekintenties dan een
 * geplande bandenwissel, met eigen inhoud — geen kopie met een andere kop.
 */
export const SPOED_AANTAL = 400;
export const SEIZOEN_AANTAL = 400;

export const spoedPlaatsen: Plaats[] = plaatsenOpGrootte.slice(0, SPOED_AANTAL);
export const seizoenPlaatsen: Plaats[] = plaatsenOpGrootte.slice(0, SEIZOEN_AANTAL);

const spoedSet = new Set(spoedPlaatsen.map((p) => p.slug));
const seizoenSet = new Set(seizoenPlaatsen.map((p) => p.slug));

export function heeftSpoedPagina(slug: string): boolean {
  return spoedSet.has(slug);
}

export function heeftSeizoenPagina(slug: string): boolean {
  return seizoenSet.has(slug);
}

export function provincieSlug(provincie: Provincie): string {
  return provincie
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

export function getProvincieBySlug(slug: string): Provincie | undefined {
  return PROVINCIES.find((p) => provincieSlug(p) === slug);
}

export function plaatsenInProvincie(provincie: Provincie): Plaats[] {
  return plaatsen.filter((p) => p.provincie === provincie);
}

export function provinciesMetPlaatsen(): Provincie[] {
  return PROVINCIES.filter((p) => plaatsen.some((s) => s.provincie === p));
}

/** Buurplaatsen die zelf een pagina hebben — voor interne links. */
export function buurPlaatsen(plaats: Plaats, max = 6): Plaats[] {
  return plaats.buren
    .map((slug) => bySlug.get(slug))
    .filter((p): p is Plaats => p !== undefined)
    .slice(0, max);
}
